        StaticItem("Skull Goblet", "Ornately carved skulls sculpted into goblets\nto make any drinking from it feel like a\nbadass\n★Event Actor Approved★\nSigned by KBR.", "minecraft:skull", ""),
        StaticItem("Crushed Helm of Torug", "A badly damaged helmet of the Dreadknight\nTorug (bromadan). The evil energy within has\nbeen snuffed out.", "minecraft:skull", ""),
        StaticItem("Golem Eye", "An eye from a slain Golem.\n★Player Approved★\nSigned by Beast720.", "minecraft:emerald", ""),
