        StaticItem("Beaded Raven Feather Necklace", "A beaded Druid necklace with a raven feather\nin the middle. It indicates the one who owns\nthis necklace has finished their Druidic\ntasks and has been attuned.\n★Player Approved★\nSigned by Priestess Nynaeve.", "minecraft:string", ""),
        StaticItem("Flute", "A very fancy flute that seemed to have been\nspecially made.", "minecraft:stick", ""),
        StaticItem("Mana-Infused Giant Raven Meat", "★Event Actor Approved★\nSigned by Murlocs.\nThe rotten food reeks of fungi.", "minecraft:beef", ""),
