        StaticItem("Prismarine Crystal Necklace", "A single piece of cut prismarine hangs\nfrom a delicate silver chain. It shines\nbrilliantly in the light, and it's color\nis reminiscent of a shallow bay.", "minecraft:prismarine_crystals", ""),
        StaticItem("Salmon Meat", "A piece of salmon meat from a giant salmon,\nstretched far but of impeccable high quality.\n★Event Actor Approved★\nSigned by Chaw.", "minecraft:leather", ""),
        StaticItem("Salmon", "A scrumptious whole salmon. It could be used\nto make sushi.\n★Event Actor Approved★\nSigned by Chaw.", "minecraft:skull", ""),
        StaticItem("Staff of the RedPanda Druid", "The staff is made from a rather large branch\nfrom an Orange tree. The bark has been peeled\noff and the wood smooth to the touch.\nEmbedded into the staff are vines of copper,\nstarting at the bottom of the staff and\nsnaking their way up to the top. Dotted\naround the staff are chunks of amber, carved\ninto the rough shape of a Redpanda. Around\neach panda a different scene in nature has\nbeen carved into the wood. The staff itself\nsmells faintly of oranges.\n★Game Moderator Approved★\nSigned by sidmmvv.", "minecraft:wooden_hoe", ""),
        StaticItem("Ordinary Stones", "Before you is an ordinary stone from the\nground. There is nothing unusual about it. It\nis just a stone.\n★Player Approved★\nSigned by Aiza Vincrute.", "minecraft:stone_button", ""),
        StaticItem("Principalirt Passport", "OFFICIAL PRINCIPALITY PASSPORT: ACCEPTED BY\nLORD LAEN DRAKON; [Name: Wydren Volarenl]\n[Race: Wood Elf] [Eye Color: Green] [Hair\nColor: Brown] [Weight: 150-180] [Height: 5'8]\nNaturalized Citizen.\n★Game Moderator Approved★\nSigned by [High Chancellor] Laen Drakon.", "minecraft:paper", ""),
        StaticItem("Sturgeon", "108.0lbs, 115\nExpires in 1d 23h 18m", "minecraft:fish", ""),
        StaticItem("Honeyed Ham", "Food: 8\nSaturation: 15.0\nThe rotten food reeks of fungi.", "minecraft:cooked_porkchop", ""),
        StaticItem("Fennic 100 Mina Tax Receipt", "A receipt issued by the government of the\nPrincedom of Fenn for 100 mina worth of tax.\n★Player Approved★\nSigned by enis__.", "minecraft:paper", ""),
        StaticItem("Fennic 50 Mina Tax Receipt", "A receipt issued by the government of the\nPrincedom of Fenn for 50 mina worth of tax.\n★Player Approved★\nSigned by enis__.", "minecraft:paper", ""),
        StaticItem("Fennic 35 Mina Tax Receipt", "A receipt issued by the government of the\nPrincedom of Fenn for 35 mina worth of tax.\n★Player Approved★\nSigned by enis__.", "minecraft:paper", ""),
        StaticItem("Fennic 75 Mina Tax Receipt", "A receipt issued by the government of the\nPrincedom of Fenn for 75 mina worth of tax.\n★Player Approved★\nSigned by enis__.", "minecraft:paper", ""),
        StaticItem("Devilish Topaz Staff", "Arcane II\nA excellent staff, perhaps\nwith a hint of magical affinity.\nDurability: 256/256", "minecraft:golden_hoe", ""),
        StaticItem("Lemon Tea", "Lemon + Hot Water\n★Player Approved★\nSigned by Grand Princess Arahaelth Tundrak.", "minecraft:potion", ""),
        StaticItem("Tincture of Blissfoil", "A brown glass bottle filled with a tenebrous,\nacrid-smelling fluid. When applied to wounds,\nit produces a brief stinging sensation\nfollowed by complete numbness, allowing the\nuser to painlessly cleanse wounds.\n★Player Approved★\nSigned by Tavern_Roleplay.", "minecraft:potion", ""),
        StaticItem("Rubber Ball", "", "minecraft:red_glazed_terracotta", ""),
        StaticItem("Vial of Deterioration", "An acid which corodes a lot of organic\nmaterials, yet at a slow pace. Easily\nwashed with water and soup.\nMore ingredients can be added.", "minecraft:potion", ""),
        StaticItem("Magmaskin Potion", "This vermilion colored potion pulsates\nwith warmth. If consumed the user's skin\nstarts to smoke, and it hardens like\nbreaking stone. The cracks gain a bright\nred glow, while the drinker is in agony.\nMore ingredients may be added.", "minecraft:potion", ""),
        StaticItem("Dragon's Gale", "An odd, breezy concoction that,\ndespite having volume, would be next\nto useless as a paperweight.\nMore ingredients can be added.", "minecraft:potion", ""),
        StaticItem("Toxic Slur", "A thick black liquid, alike to tar. It even\nreeks of toxic material.\nNo one would ever willingly drink this.\nMore ingredients may be added.", "minecraft:potion", ""),
        StaticItem("Petrification Potion", "The effects take hold of the body quickly.\nWith a crushing sensation, the skin cracks\nand becomes stone-like in texture and property.\nThe user becomes indestructible but also\nimmolbilised, like a statue.\nMore ingredients may be added.", "minecraft:potion", ""),
        StaticItem("Bubbling Death", "The bubbling in this potion is from a\ncorrosive creation. The body of the drinker\nquickly gets destroyed from the inside.\nMore ingredients may be added.", "minecraft:potion", ""),
        StaticItem("Nightshade", "A terrifying concoction which is prone\nto melting glass, so a stone containment\nwould be required for this liquid. Due\nto how bright this smooth running\nconcoction is, it would be painful to\neven look at. Nether knows what it\nwould be like if one were to touch it,\nlet alone drink it.\nMore ingredients may be added.", "minecraft:potion", ""),
        StaticItem("Seashell of Cerridwen", "A seashell that has seen the test of time.\nBattered and beaten, yet still colorful and\nvibrant in all its glory. With an array of\ncolors on it, if held up to the light, it\nwill display numerous moving images against\nnearby surface. These images would appear to\nbe an absract visualization of life.\n★Game Moderator Approved★\nSigned by [Wisteria Druid] Renn.", "minecraft:dye", ""),
        StaticItem("Self rolling dice", "These dice appear to roll on their own... How odd.\n*Moderator Approved*\nLifeforceIsMana approved this item.", "minecraft:stone_button", ""),
        StaticItem("Tragedy Stack", "A stack of cards with tragedies painted\nacross them, if staring too long at them they\ncome to life - But only for the user.\n★Game Moderator Approved★\nSigned by JVQ.", "minecraft:paper", ""),
        StaticItem("Sailors Delight", "A delicious broth of freshly\ncooked fish.\nThe rotten food reeks of fungi.", "minecraft:mushroom_stew", ""),
        StaticItem("big hat", "big hat only big friends can get", "minecraft:iron_helmet", ""),
        StaticItem("Unlimited Tikcet", "With this ticket, show it to those who hold\nevents requiring tickets! Any amount or times\nyou can pass, you're good to go!\n★Player Approved★\nSigned by Imperial Administration.", "minecraft:book", ""),
        StaticItem("Bone-Shank", "", "minecraft:bone", ""),
        StaticItem("Elegant Sponge", "", "minecraft:sponge", ""),
        StaticItem("Frost Vines", "It often is seen growing beneath shady trees\neasily notable due to its deep blue hue. Its\nuse in the medical field allows it to be\nrubbed into skin, numbing pain and loosening\nstiff muscle. Prolonged usage wil cause\ntemporary numbing", "minecraft:vine", ""),
        StaticItem("Elrow Berries", "A notably ruby berry that only grows in the\ncold north, it is consumed as a spice to add\nfire to a dish. However overdosage of the\nberries will cause inflammation in the body.\nIt is also known to make a greay curry!", "minecraft:nether_wart", ""),
        StaticItem("Diddyfunkles", "Considered an irritable but useful plant, the\nDiddyfunkle coats itself with a very itchy\nsubstance named: \"Diddyfunklites\", appearing\nas purple stems jutting out from the centre\nball. Can cause rashing, hallucinations, and\ndeliciousness.", "minecraft:stained_hardened_clay", ""),
        StaticItem("Night Sap", "Only found in deformed oak trees, the thich\nhoney like substance shines brilliantly when\nextracted. The smooth substance causes\nmuscles to relax and strike the patient with\ndrowsiness. Aftereffects include strong\nmigraines, and being addicted.", "minecraft:wool", ""),
        StaticItem("Aurum Sphere", "A well crafted small sphere of pure Aurum.", "minecraft:gold_ingot", ""),
        StaticItem("Lion Plushie", "A large golden lion plushie with faux\nfur. It is very soft to the touch.\n★Player Approved★\nSigned by TheRiddleSphynx.", "minecraft:wool", ""),
        StaticItem("Apple Bread", "Food: 4\nSaturation: 4.0\nThe rotten food reeks of fungi.", "minecraft:bread", ""),
        StaticItem("Virulent Slime", "This potion resembles that of tar. Deep\npurple in color, this brew will soak into the\nusers skin, creating a revolting odor as it\nbegins to work, a bubbling feeling felt inside,\nirresistible not to scratch, as it sears your skin.\nMore ingredients may be added.", "minecraft:potion", ""),
        StaticItem("Calaway Boost 350 \"Turtle Dove", "Brabant and Royalic came together to release\nthe Calaway Boost 350 \"Turtle Dove.\" 1588", "minecraft:chainmail_boots", ""),
        StaticItem("Norlandic Bone Hand-axe", "A tiny, bone hand-axe made out of the bones\nof slain Oren troops! A wonderful little\nsouvenir of Norland, only sold at Ibarigne's\nstall.\n★Player Approved★\nSigned by Jacobcraft04.", "minecraft:bone", ""),
        StaticItem("✮ Festival de Philip ✮", "A small piece of purple hued parchment\ndecorated with elaborate details, holding\netching on the backside; Thank you for\njoining us on this festival devoted for the\nbattled devoted to death of Philip Owyn on\nthe 10th of The First Seed, 1626. GOD guide\nyou!\n★Player Approved★\nSigned by ♛ The Imperial Administration ♛.", "minecraft:banner", "")
    )

